def escape_ts(s):
    return s.replace('\\', '\\\\').replace('`', '\\`').replace('${', '\\${')

def write_ts(data, out_path):
    lines = [HEADER]
    for cat, questions in data.items():
        lines.append(f'  // ===== {cat} =====')
        for i, q in enumerate(questions, 1):
            tier, text, opts, ci, expl, fact = q
            opts_str = ', '.join(f'"{escape_ts(o)}"' for o in opts)
            extra_parts = []
            if expl:
                extra_parts.append(f'explanation: "{escape_ts(expl)}"')
            if fact:
                extra_parts.append(f'funFact: "{escape_ts(fact)}"')
            extra = ', {' + ', '.join(extra_parts) + '}' if extra_parts else ''
            lines.append(f'  qx("{cat}", {tier}, "{escape_ts(text)}", [{opts_str}], {ci}, {i}{extra}),')
        lines.append('')
    lines.append(FOOTER)
    with open(out_path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(lines))
    print(f'Wrote {out_path} with {sum(len(v) for v in data.values())} questions.')

if __name__ == '__main__':
    import os
    out = os.path.join(os.path.dirname(__file__), '../src/lib/questionsExpanded_p1.ts')
    write_ts(DATA, out)
